<template>
 <div class="v2-workspace" :class="{ 'v2-collapsed': collapsed, 'v2-mobile-open': mobileOpen }">
  <a class="v2-skip" href="#v2-main">Vai al contenuto</a>
  <aside id="v2-navigation" ref="sidebar" class="v2-sidebar" :inert="isMobile && !mobileOpen" :role="isMobile && mobileOpen ? 'dialog' : undefined" :aria-modal="isMobile && mobileOpen ? true : undefined" aria-label="Navigazione amministrazione" @keydown="drawerKeydown">
   <a class="v2-brand" :href="path('dashboard')" @click.prevent="go('dashboard')" aria-label="ArenaBoostX, panoramica"><span class="v2-brand-mark"><V2Icon name="boost" :size="23" /></span><strong>ArenaBoost<span>X</span><small>CLUB WORKSPACE</small></strong></a>
   <div class="v2-club"><span class="v2-club-avatar">{{ (c.organizationName || c.organizationSlug || 'A').slice(0,2).toUpperCase() }}</span><div><strong>{{ c.organizationName || c.organizationSlug }}</strong><span>Amministrazione società</span></div><span class="v2-club-dot" title="Sessione verificata"></span></div>
   <nav aria-label="Sezioni della società" class="v2-nav">
    <div v-for="group in groups" :key="group.label" class="v2-nav-group"><p>{{ group.label }}</p><a v-for="item in group.items" :key="item.id" :href="path(item.id)" :class="{ active: section === item.id }" :aria-current="section === item.id ? 'page' : undefined" :title="collapsed ? item.label : undefined" @click.prevent="go(item.id)"><V2Icon :name="item.id" :size="19" /><span>{{ item.label }}</span><span v-if="item.id === 'events' && c.activeEventEntry" class="v2-nav-live"></span></a></div>
   </nav>
   <div class="v2-sidebar-footer"><a v-if="!c.isStaff" :href="path('lottery')" :class="{ active: section === 'lottery' }" :title="collapsed ? 'Lotteria e vincitori' : undefined" @click.prevent="go('lottery')"><V2Icon name="lottery" :size="19" /><span>Lotteria e vincitori</span></a><a v-if="c.isSuperAdmin" :href="path('settings')" :class="{ active: section === 'settings' }" :title="collapsed ? 'Votazioni e notifiche' : undefined" @click.prevent="go('settings')"><V2Icon name="settings" :size="19" /><span>Votazioni e notifiche</span></a><button type="button" :aria-expanded="!collapsed" aria-label="Comprimi o espandi navigazione" @click="toggleCollapsed"><V2Icon :name="collapsed ? 'chevron-right' : 'chevron-left'" :size="19" /><span>Comprimi menu</span></button><button type="button" class="v2-mobile-close" @click="mobileOpen = false"><V2Icon name="close" :size="19" /> Chiudi menu</button></div>
  </aside>
  <div class="v2-workspace-body" :inert="isMobile && mobileOpen">
   <header class="v2-topbar"><div class="v2-toolbar"><button ref="menuButton" class="v2-button v2-icon-button v2-mobile-toggle" aria-label="Apri navigazione" :aria-expanded="mobileOpen" aria-controls="v2-navigation" type="button" @click="mobileOpen = true"><V2Icon name="menu" /></button><span class="v2-top-context">Workspace società</span><span class="v2-top-divider">/</span><span>{{ meta.group }}</span></div><div class="v2-toolbar"><a class="v2-public-link" :href="`/${encodeURIComponent(c.organizationSlug)}/new`" target="_blank" rel="noopener">Apri area fan <V2Icon name="arrow-up-right" :size="15" /></a><button class="v2-account" type="button" :aria-label="`Menu account di ${c.activeUsername}`" :aria-expanded="accountOpen" aria-controls="v2-account-menu" @click="accountOpen = !accountOpen"><span>{{ c.activeUsername.slice(0,2).toUpperCase() }}</span><div><strong>{{ c.activeUsername }}</strong><small>{{ roleLabel }}</small></div><V2Icon name="chevron-right" :size="15" /></button></div><div v-if="accountOpen" id="v2-account-menu" class="v2-account-menu" @keydown.esc="accountOpen=false"><strong>{{ c.activeUsername }}</strong><small>{{ c.organizationName || c.organizationSlug }} · {{ roleLabel }}</small><a :href="`/${encodeURIComponent(c.organizationSlug)}/admin`">Apri admin precedente <V2Icon name="arrow-up-right" :size="15" /></a><button type="button" @click="c.confirmAction('Uscire dal workspace?', 'Dovrai accedere nuovamente per continuare.', () => c.logout())"><V2Icon name="logout" :size="17" /> Esci</button></div></header>
   <main id="v2-main" ref="main" class="v2-work-area" tabindex="-1">
    <header class="v2-page-heading"><div><p class="v2-eyebrow">{{ c.organizationName || c.organizationSlug }} <span>/</span> {{ meta.group }}</p><h1>{{ meta.label }}</h1><p>{{ meta.description }}</p></div><div class="v2-toolbar"><button v-if="section === 'dashboard'" class="v2-button" type="button" :disabled="c.initialLoading || c.busy('refresh')" @click="c.run('refresh', c.refreshWorkspace)"><V2Icon name="refresh" :size="17" />Aggiorna</button><button v-if="section === 'dashboard' || section === 'events' && !detail" type="button" class="v2-button v2-primary" @click="go('events','create')"><V2Icon name="plus" :size="18" /> Nuovo evento</button></div></header>
    <slot />
    <footer class="v2-work-footer"><span>ArenaBoostX <span>·</span> Club workspace</span><span>{{ c.organizationName || c.organizationSlug }}</span></footer>
   </main>
  </div>
  <button v-if="isMobile && mobileOpen" class="v2-drawer-backdrop" tabindex="-1" type="button" aria-label="Chiudi navigazione" @click="mobileOpen = false"></button>
 </div>
</template>
<script setup>
import { computed, inject, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue';
import { navigation } from '../config/navigation';
import { adminV2Path } from '../router/routes';
import V2Icon from '../components/shared/V2Icon.vue';
const props = defineProps({ section: String, detail: String, meta: Object }); const c = inject('admin-v2');
const collapsed = ref(false), mobileOpen=ref(false), isMobile=ref(false), accountOpen=ref(false), sidebar=ref(null), menuButton=ref(null), main=ref(null);
let media; let overflow;
const groups = computed(()=>navigation.map(g=>({...g,items:g.items.filter(i=>i.id==='merch'?c.isSuperAdmin:c.availableTabs.some(t=>t.id===i.id))})).filter(g=>g.items.length));
const roleLabel = computed(()=>c.isSuperAdmin?'Amministratore':c.isBarAdmin?'Operatore bar':'Staff società');
const path = section=>adminV2Path(c.organizationSlug,section);
function go(section, detail=''){c.navigate(section,detail);mobileOpen.value=false;accountOpen.value=false;}
function toggleCollapsed(){collapsed.value=!collapsed.value;try{localStorage.setItem('abx:v2:sidebar',collapsed.value?'collapsed':'expanded');}catch{}}
function resize(){isMobile.value=media.matches;if(!media.matches)mobileOpen.value=false;}
function drawerKeydown(e){if(!isMobile.value||!mobileOpen.value)return;if(e.key==='Escape'){e.preventDefault();mobileOpen.value=false;}if(e.key==='Tab'){const nodes=[...sidebar.value.querySelectorAll('a[href],button')].filter(el=>el.getClientRects().length);const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}}
watch(mobileOpen,async open=>{if(open&&isMobile.value){overflow=document.body.style.overflow;document.body.style.overflow='hidden';await nextTick();sidebar.value?.querySelector('a')?.focus();}else if(overflow!==undefined){document.body.style.overflow=overflow;overflow=undefined;menuButton.value?.focus();}});
watch(()=>props.section,async()=>{accountOpen.value=false;await nextTick();main.value?.focus({preventScroll:true});});
onMounted(()=>{media=window.matchMedia('(max-width: 1000px)');resize();media.addEventListener('change',resize);try{collapsed.value=localStorage.getItem('abx:v2:sidebar')==='collapsed';}catch{}});
onBeforeUnmount(()=>{media?.removeEventListener('change',resize);if(overflow!==undefined)document.body.style.overflow=overflow;});
</script>
<style scoped>
