ecoration:none}.v2-nav a.active,.v2-sidebar-footer a.active{background:#e9f3ed;color:#176447;font-weight:650}.v2-nav-live{width:6px;height:6px;background:#26875c;border-radius:50%;margin-left:auto}.v2-sidebar-footer{border-top:1px solid var(--v2-line);padding-top:10px}.v2-workspace-body{min-width:0}.v2-topbar{position:relative;display:flex;align-items:center;justify-content:space-between;gap:16px;padding:0 36px;height:80px;background:#ffffffd9;border-bottom:1px solid var(--v2-line);font-size:12px;color:var(--v2-muted);z-index:90}.v2-top-context{color:#78868e}.v2-top-divider{color:#bec8ce;margin:0 3px}.v2-public-link{display:flex;align-items:center;gap:5px;font-size:11px;color:var(--v2-muted);margin-right:20px}.v2-account{display:flex;align-items:center;gap:10px;min-height:44px;text-align:left;color:var(--v2-ink)}.v2-account>span{display:grid;place-items:center;width:34px;height:34px;background:#e7edf1;border:1px solid #d2dce3;border-radius:50%;font-size:11px;font-weight:650}.v2-account strong{display:block;font-size:11px;font-weight:650}.v2-account small{display:block;font-size:10px;margin-top:1px}.v2-account>svg{margin-left:10px;transform:rotate(90deg)}.v2-account-menu{position:absolute;top:70px;right:30px;width:270px;background:#fff;border:1px solid var(--v2-line);border-radius:12px;padding:16px;display:grid;gap:9px;box-shadow:0 12px 40px #172b3520}.v2-account-menu small{display:block;border-bottom:1px solid var(--v2-line);padding-bottom:14px}.v2-account-menu a,.v2-account-menu button{display:flex;align-items:center;justify-content:space-between;min-height:44px;font-size:12px;color:var(--v2-ink);text-align:left}.v2-account-menu button{color:var(--v2-danger)}.v2-work-area{padding:34px 36px 0;max-width:1660px;margin:auto;min-height:calc(100vh - 80px);outline:none}.v2-page-heading{display:flex;align-items:center;justify-content:space-between;gap:24px;margin-bottom:30px}.v2-page-heading h1{margin:10px 0 8px}.v2-page-heading>div>p:last-child{font-size:13px;color:var(--v2-muted)}.v2-page-heading .v2-eyebrow{font-size:10px;letter-spacing:1.1px}.v2-eyebrow>span{color:#adb9bf;margin:0 7px}.v2-work-footer{display:flex;justify-content:space-between;gap:16px;font-size:10px;color:#70818b;padding:28px 0 20px;margin-top:24px;border-top:1px solid var(--v2-line)}.v2-work-footer span>span{margin:0 8px}.v2-mobile-toggle,.v2-mobile-close,.v2-drawer-backdrop{display:none}.v2-collapsed{grid-template-columns:84px minmax(0,1fr)}.v2-collapsed .v2-sidebar{padding-inline:12px}.v2-collapsed .v2-brand{padding-inline:10px}.v2-collapsed .v2-brand strong,.v2-collapsed .v2-club>div,.v2-collapsed .v2-club-dot,.v2-collapsed .v2-nav-group>p,.v2-collapsed .v2-nav a>span,.v2-collapsed .v2-sidebar-footer a>span,.v2-collapsed .v2-sidebar-footer button>span{display:none}.v2-collapsed .v2-club{padding:9px 12px}.v2-collapsed .v2-nav a,.v2-collapsed .v2-sidebar-footer a,.v2-collapsed .v2-sidebar-footer button{justify-content:center}.v2-collapsed .v2-nav-group{margin-bottom:12px}
@media(max-width:1200px){.v2-topbar{padding-inline:24px}.v2-work-area{padding:28px 24px 0}.v2-page-heading{align-items:flex-start}.v2-page-heading>.v2-toolbar{justify-content:flex-end}.v2-public-link{margin-right:5px}}@media(max-width:1000px){.v2-workspace,.v2-workspace.v2-collapsed{display:block}.v2-sidebar{position:fixed;inset:0 auto 0 0;width:280px;height:100dvh;transform:translateX(-100%);transition:transform .2s;z-index:130;padding:24px 16px}.v2-mobile-open .v2-sidebar{transform:translateX(0)}.v2-mobile-toggle{display:inline-flex}.v2-drawer-backdrop{display:block;position:fixed;inset:0;background:#10212b88;z-index:120}.v2-sidebar-footer button:not(.v2-mobile-close){display:none}.v2-mobile-close{display:flex}.v2-collapsed .v2-brand strong,.v2-collapsed .v2-club>div,.v2-collapsed .v2-club-dot,.v2-collapsed .v2-nav-group>p,.v2-collapsed .v2-nav a>span,.v2-collapsed .v2-sidebar-footer a>span,.v2-collapsed .v2-sidebar-footer button>span{display:revert}.v2-collapsed .v2-nav a,.v2-collapsed .v2-sidebar-footer a,.v2-collapsed .v2-sidebar-footer button{justify-content:flex-start}.v2-topbar{height:72px}.v2-work-area{min-height:calc(100vh - 72px)}}@media(max-width:640px){.v2-topbar{padding:0 16px;gap:10px}.v2-top-context,.v2-top-divider,.v2-public-link,.v2-account>div,.v2-account>svg{display:none}.v2-work-area{padding:24px 16px 0}.v2-page-heading{display:grid;gap:18px;margin-bottom:24px}.v2-page-heading>.v2-toolbar{justify-content:flex-start}.v2-page-heading .v2-eyebrow{font-size:9px}.v2-work-footer>span:last-child{display:none}.v2-account-menu{right:16px}.v2-topbar>.v2-toolbar{flex-wrap:nowrap}}
</style>
